const planets=[
 ['Mercury',88,1407.6,.387,'#b9aaa0',4,'THE SWIFTEST PLANET','A rocky, cratered world that races around the Sun faster than any other planet.'],
 ['Venus',224.7,-5832.5,.723,'#d9bb83',7,'OUR NEIGHBOURING WORLD','Wrapped in thick clouds, Venus spins slowly in the opposite direction to most planets.'],
 ['Earth',365.256,23.9345,1,'#66a9cb',8,'OUR HOME PLANET','An ocean world with a life-filled surface. Our small blue home in the vastness of space.'],
 ['Mars',686.98,24.6229,1.524,'#d77d59',6,'THE RED PLANET','A dusty desert world with towering volcanoes, ancient riverbeds and two tiny moons.'],
 ['Jupiter',4332.59,9.925,5.203,'#d3b18b',20,'KING OF THE PLANETS','A giant of swirling clouds. Jupiter has the fastest rotation of all eight planets.'],
 ['Saturn',10759.22,10.656,9.537,'#d8c393',17,'THE RINGED WORLD','An airy gas giant surrounded by magnificent rings of ice and rocky fragments.'],
 ['Uranus',30688.5,-17.24,19.19,'#9dd9d9',12,'THE TILTED ICE GIANT','A cool blue-green giant with an extreme axial tilt and a retrograde rotation.'],
 ['Neptune',60182,16.11,30.07,'#5c83dc',12,'BEYOND THE BLUE','Dark, cold and swept by fierce winds, Neptune traces the outermost planetary orbit.']
].map((p,i)=>({name:p[0],period:p[1],rotation:p[2],au:p[3],color:p[4],r:p[5],type:p[6],description:p[7],phase:[2.6,4.5,1.2,3.6,5.6,2.2,.3,4][i]}));
const $=id=>document.getElementById(id),canvas=$('space'),ctx=canvas.getContext('2d');let w,h,dpr,seconds=0,speed=100,paused=false,selected=2,last=performance.now(),hits=[];
let seed=41;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}const stars=Array.from({length:420},()=>[rand(),rand(),rand(),rand()]);
planets.forEach((p,i)=>{const b=document.createElement('button');b.innerHTML=`<span class="dot" style="--color:${p.color}"></span>${p.name}`;b.onclick=()=>select(i);$('planets').appendChild(b)});
function select(i){selected=i;const p=planets[i];$('name').textContent=p.name;$('number').textContent=`${String(i+1).padStart(2,'0')} / 08`;$('type').textContent=p.type;$('description').textContent=p.description;$('orbit').textContent=p.period.toLocaleString()+' Earth days';$('rotation').textContent=Math.abs(p.rotation)+' hours'+(p.rotation<0?' · retrograde':'');$('distance').textContent=p.au+' AU';$('globe').style.background=`radial-gradient(circle at 30% 25%, #f2e8cc, ${p.color} 35%, #070d19 95%)`;[...$('planets').children].forEach((b,j)=>{b.classList.toggle('active',j===i);b.setAttribute('aria-pressed',j===i)})}select(2);
$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',paused?'Resume simulation':'Pause simulation')};$('reset').onclick=()=>{seconds=0;speed=100;$('speed').value='100';$('equivalent').textContent='1 second = 100 seconds'};$('speed').onchange=e=>{speed=Number(e.target.value);$('equivalent').textContent=`1 second = ${speed.toLocaleString()} seconds`};
function resize(){w=innerWidth;h=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function sphere(p,x,y,r){ctx.save();ctx.translate(x,y);if(p.name==='Saturn'){ctx.save();ctx.rotate(-.35);ctx.strokeStyle='#c8b88b77';ctx.lineWidth=r*.43;ctx.beginPath();ctx.ellipse(0,0,r*1.9,r*.6,0,0,Math.PI*2);ctx.stroke();ctx.restore()}ctx.save();ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.clip();ctx.fillStyle=p.color;ctx.fillRect(-r,-r,r*2,r*2);const spin=seconds/(p.rotation*3600)*Math.PI*2;for(let j=0;j<12;j++){const lon=spin+j*2.399;const lat=Math.sin(j*12.7)*.8;if(Math.cos(lon)<0)continue;ctx.fillStyle=p.name==='Earth'?(j%3?'#5c9473':'#c2dbd4'):j%2?'#ffffff26':'#291b222e';ctx.beginPath();if(['Jupiter','Saturn','Uranus','Neptune'].includes(p.name)){ctx.ellipse(Math.sin(lon)*r*.3,lat*r,r*1.2,r*.05,0,0,Math.PI*2)}else{ctx.ellipse(Math.sin(lon)*r*Math.sqrt(1-lat*lat),lat*r,r*.24*Math.max(.1,Math.cos(lon)),r*.17,j,0,Math.PI*2)}ctx.fill()}const shade=ctx.createRadialGradient(-r*.45,-r*.45,0,r*.2,r*.1,r*1.25);shade.addColorStop(0,'#ffffff28');shade.addColorStop(.4,'#00000000');shade.addColorStop(1,'#000e');ctx.fillStyle=shade;ctx.fillRect(-r,-r,r*2,r*2);ctx.restore();if(selected===planets.indexOf(p)){ctx.strokeStyle='#b9f4cf88';ctx.lineWidth=1;ctx.beginPath();ctx.arc(0,0,r+6,0,Math.PI*2);ctx.stroke()}ctx.restore()}
function frame(now){const dt=Math.max(0,(now-last)/1000);last=now;if(!paused)seconds+=dt*speed;ctx.clearRect(0,0,w,h);const mobile=w<650,cx=mobile?w*.5:w*.45,cy=mobile?355:Math.min(h*.48,440),scale=mobile?w*.44:Math.min(w*.325,(h-240)*.77),squash=mobile?.52:.58;
 stars.forEach(([x,y,r,a])=>{ctx.fillStyle=`rgba(180,201,220,${.12+a*.48})`;ctx.beginPath();ctx.arc(x*w,y*h,.3+r*.8,0,7);ctx.fill()});const glow=ctx.createRadialGradient(cx,cy,0,cx,cy,scale*.65);glow.addColorStop(0,'#8d5b1115');glow.addColorStop(1,'#0000');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);hits=[];
 planets.forEach((p,i)=>{const radius=scale*(.18+i*.113);if($('orbits').checked){ctx.strokeStyle=selected===i?'#9fceb831':'#6f84951e';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(cx,cy,radius,radius*squash,-.18,0,Math.PI*2);ctx.stroke()}const a=p.phase+seconds/(p.period*86400)*Math.PI*2;const ox=Math.cos(a)*radius,oy=Math.sin(a)*radius*squash;const x=cx+ox*Math.cos(-.18)-oy*Math.sin(-.18),y=cy+ox*Math.sin(-.18)+oy*Math.cos(-.18);const r=p.r*(mobile?.7:1);sphere(p,x,y,r);hits.push({x,y,r:Math.max(r,14),i});if($('labels').checked){ctx.font=`${selected===i?'500':'400'} ${mobile?9:10}px 'DM Sans',sans-serif`;ctx.textAlign='center';ctx.fillStyle=selected===i?'#d5f3e0':'#8a96a3';ctx.fillText(p.name,x,y+r+20)}});
const sunR=mobile?17:25;const halo=ctx.createRadialGradient(cx,cy,sunR*.7,cx,cy,sunR*3.7);halo.addColorStop(0,'#ffbf4e77');halo.addColorStop(.35,'#ff9e1d18');halo.addColorStop(1,'#ff8b0000');ctx.fillStyle=halo;ctx.beginPath();ctx.arc(cx,cy,sunR*3.7,0,7);ctx.fill();const sun=ctx.createRadialGradient(cx-8,cy-8,1,cx,cy,sunR);sun.addColorStop(0,'#fff4b4');sun.addColorStop(.6,'#ffd563');sun.addColorStop(1,'#e89525');ctx.fillStyle=sun;ctx.beginPath();ctx.arc(cx,cy,sunR,0,7);ctx.fill();if($('labels').checked){ctx.textAlign='center';ctx.font='9px sans-serif';ctx.fillStyle='#d2ae6b';ctx.fillText('SUN',cx,cy+sunR+18)}$('elapsed').textContent='+'+(seconds/86400).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})+' days';requestAnimationFrame(frame)}requestAnimationFrame(frame);
document.addEventListener('click',e=>{if(e.target.closest('button,a,select,input,aside,footer,header'))return;const hit=hits.find(p=>Math.hypot(e.clientX-p.x,e.clientY-p.y)<p.r+7);if(hit)select(hit.i)});document.querySelector('main').addEventListener('mousemove',e=>{e.currentTarget.style.cursor=hits.some(p=>Math.hypot(e.clientX-p.x,e.clientY-p.y)<p.r+7)?'pointer':'default'});
